"use client"

import { createParts } from "@ui-sdk/react/primitive"
import {
  createSliderController,
  Slider,
  SliderControl,
  SliderThumb,
  SliderTrack,
  type SliderValueChangeDetails,
} from "@ui-sdk/react/slider"
import { Toggle, ToggleIcon } from "@ui-sdk/react/toggle"
import { PauseIcon, PlayIcon } from "lucide-react"
import { memo, useMemo, useRef, useState, type PointerEvent as ReactPointerEvent, type RefObject } from "react"

import { ControlTooltip } from "@/components/ui/tooltip"
import { useVinylClock } from "@/components/ui/use-vinyl-clock"
import { useVinylMedia } from "@/components/ui/use-vinyl-media"
import { useVinylScene } from "@/components/ui/use-vinyl-scene"
import { useVinylStage } from "@/components/ui/use-vinyl-stage"
import { vinylScrubber } from "@/components/ui/vinyl-scrubber-primitive"
import { recordPointAt, secondsPerTurn } from "@/components/ui/vinyl-scrubber-view"
import { cn } from "@/lib/utils"

const { Root: VinylScrubberRoot } = createParts(vinylScrubber, { root: "div" })

type VinylScrubberLabels = {
  /** Names the timeline, a slider in seconds, for screen readers and agents. */
  position: string
  /** Names the play button, which stays pressed while it plays. */
  play: string
}

const vinylScrubberLabels: VinylScrubberLabels = { position: "Position", play: "Play" }

/** Why the position or playback changed (`drag`, `step-key`, `scratch`, `imperative`…), and `cancel()` to keep it. */
type VinylChangeDetails = {
  reason: string
  event: Event | undefined
  cancel: () => void
  readonly canceled: boolean
}

type VinylScrubberState = { disabled: boolean; playing: boolean; time: number; duration: number }

type VinylScrubberProps = {
  /** The accessible name of the player as a whole. */
  label: string
  /** The audio or video it controls: it follows its time and playback, and seeks, plays and pauses it. */
  media?: RefObject<HTMLMediaElement | null>
  /** The position in seconds. Pass it to control the scrubber. */
  value?: number
  defaultValue?: number
  /** The length in seconds; read from `media` without it. */
  duration?: number
  /** Runs on every step of a drag, a scratch, a key or an agent's seek. */
  onValueChange?: (seconds: number, details: VinylChangeDetails) => void
  /** Whether it plays. Pass it to control playback. */
  playing?: boolean
  defaultPlaying?: boolean
  onPlayingChange?: (playing: boolean, details: VinylChangeDetails) => void
  /** Loudness along the track, each from 0 to 1, drawn as the waveform; a plain groove without them. */
  peaks?: readonly number[]
  /** Seconds per arrow key; 5 by default. Page Up and Page Down move 30. */
  step?: number
  /** Printed big on the record's label. */
  title?: string
  /** Printed on the label under the title: a side, a track, an artist. */
  subtitle?: string
  disabled?: boolean
  labels?: Partial<VinylScrubberLabels>
  /** Classes for the root; a function gets the player's state. */
  className?: string | ((state: VinylScrubberState) => string | undefined)
  /** Called with each paint's duration in ms, for measuring. */
  onPaint?: (milliseconds: number) => void
}

function details(reason: string, event: Event | undefined): VinylChangeDetails {
  let canceled = false
  return {
    reason,
    event,
    cancel: () => {
      canceled = true
    },
    get canceled() {
      return canceled
    },
  }
}

function clock(seconds: number) {
  const whole = Math.max(0, Math.floor(seconds))
  const hours = Math.floor(whole / 3600)
  const minutes = Math.floor((whole % 3600) / 60)
  const rest = String(whole % 60).padStart(2, "0")
  return hours > 0 ? `${String(hours)}:${String(minutes).padStart(2, "0")}:${rest}` : `${String(minutes)}:${rest}`
}

const maxBars = 180

function waveformPath(peaks: readonly number[]) {
  const bars = Math.min(maxBars, peaks.length)
  const bucket = peaks.length / bars
  const parts: string[] = []
  for (let bar = 0; bar < bars; bar++) {
    let loudest = 0
    for (
      let index = Math.floor(bar * bucket);
      index < Math.max(Math.floor((bar + 1) * bucket), Math.floor(bar * bucket) + 1);
      index++
    ) {
      loudest = Math.max(loudest, Math.abs(peaks[index] ?? 0))
    }
    const height = Math.max(2, Math.min(1, loudest) * 92)
    parts.push(`M${(bar + 0.18).toFixed(2)} ${(50 - height / 2).toFixed(2)}h0.64v${height.toFixed(2)}h-0.64z`)
  }
  return { bars, d: parts.join("") }
}

const Waveform = memo(function Waveform({ peaks }: { peaks: readonly number[] | undefined }) {
  const wave = useMemo(() => (peaks && peaks.length > 0 ? waveformPath(peaks) : null), [peaks])
  if (!wave) return <div data-slot="vinyl-groove" aria-hidden="true" />
  return (
    <div data-slot="vinyl-waveform" aria-hidden="true">
      {/* oxlint-disable-next-line eskais/no-inline-icons -- the track's waveform, drawn from its peaks, not an icon */}
      <svg viewBox={`0 0 ${String(wave.bars)} 100`} preserveAspectRatio="none">
        <path d={wave.d} />
      </svg>
      {/* oxlint-disable-next-line eskais/no-inline-icons -- the played part of the same waveform, not an icon */}
      <svg data-played="" viewBox={`0 0 ${String(wave.bars)} 100`} preserveAspectRatio="none">
        <path d={wave.d} />
      </svg>
    </div>
  )
})

const Drawing = memo(function Drawing({
  title,
  subtitle,
}: {
  title: string | undefined
  subtitle: string | undefined
}) {
  return (
    <div data-slot="vinyl-drawing" aria-hidden="true">
      <div data-slot="vinyl-platter" />
      <div data-slot="vinyl-record">
        <div data-slot="vinyl-label">
          {title ? <span>{title}</span> : null}
          {subtitle ? <span data-subtitle="">{subtitle}</span> : null}
        </div>
      </div>
      <div data-slot="vinyl-sheen" />
      <div data-slot="vinyl-arm">
        <div data-slot="vinyl-arm-base" />
        <div data-slot="vinyl-arm-tube" />
        <div data-slot="vinyl-arm-head" />
        <div data-slot="vinyl-arm-weight" />
      </div>
    </div>
  )
})

type Scratch = { pointer: number; from: number; time: number; resume: boolean }

const drawnRecordShare = 82 / 92
const fullTurn = Math.PI * 2

function seekMedia(element: HTMLMediaElement | null | undefined, seconds: number) {
  if (element) element.currentTime = seconds
}

function playMedia(element: HTMLMediaElement | null | undefined, playing: boolean, onRefused: () => void) {
  if (!element) return
  if (playing) element.play().catch(onRefused)
  else element.pause()
}

function drawnRecordPoint(stage: HTMLElement, clientX: number, clientY: number) {
  const platter = stage.querySelector('[data-slot="vinyl-platter"]')
  if (!platter) return null
  const rect = platter.getBoundingClientRect()
  const radius = (rect.width / 2) * drawnRecordShare
  if (radius <= 0) return null
  const x = clientX - (rect.left + rect.width / 2)
  const y = clientY - (rect.top + rect.height / 2)
  return { angle: Math.atan2(y, x), distance: Math.hypot(x, y) / radius }
}

function recordPointUnder(event: ReactPointerEvent<HTMLElement>) {
  const stage = event.currentTarget
  if (stage.dataset.renderer !== "webgl") return drawnRecordPoint(stage, event.clientX, event.clientY)
  const rect = stage.getBoundingClientRect()
  if (rect.width <= 0 || rect.height <= 0) return null
  return recordPointAt(
    (event.clientX - rect.left) / rect.width,
    (event.clientY - rect.top) / rect.height,
    rect.width / rect.height,
  )
}

/**
 * A media timeline shown as a 3D turntable: the record turns with the position, a drag on it scratches and the
 * waveform under it is UI SDK's slider in seconds. It drives an `HTMLMediaElement` through `media`, or works
 * controlled. A drawn turntable stands in on the server, without WebGL and until the scene has loaded.
 */
function VinylScrubber({
  label,
  media,
  value,
  defaultValue = 0,
  duration: durationProp,
  onValueChange,
  playing: playingProp,
  defaultPlaying = false,
  onPlayingChange,
  peaks,
  step = 5,
  title,
  subtitle,
  disabled = false,
  labels: labelOverrides,
  className,
  onPaint,
}: VinylScrubberProps) {
  const labels = { ...vinylScrubberLabels, ...labelOverrides }
  const reading = useVinylMedia(media)
  const [ownTime, setOwnTime] = useState(defaultValue)
  const [ownPlaying, setOwnPlaying] = useState(defaultPlaying)
  const [slider] = useState(() => createSliderController<number>())
  const duration = durationProp ?? reading?.duration ?? 0
  const time = Math.min(duration || Infinity, value ?? (reading ? reading.time : ownTime))
  const playing = playingProp ?? (reading ? reading.playing : ownPlaying)
  const deck = useRef<HTMLDivElement>(null)
  const turntable = useRef<HTMLDivElement>(null)
  const scratch = useRef<Scratch | null>(null)
  const [scratching, setScratching] = useState(false)
  useVinylScene(deck, { time, duration, playing: playing && !scratching, onPaint })
  useVinylStage(turntable, { time, duration, playing: playing && !scratching, title, subtitle })

  const seek = (seconds: number, reason: string, event: Event | undefined) => {
    const next = Math.max(0, Math.min(duration, seconds))
    const change = details(reason, event)
    onValueChange?.(next, change)
    if (change.canceled) return false
    seekMedia(media?.current, next)
    setOwnTime(next)
    return true
  }

  const setPlaying = (next: boolean, reason: string, event: Event | undefined) => {
    const change = details(reason, event)
    onPlayingChange?.(next, change)
    if (change.canceled) return false
    playMedia(media?.current, next, () => setOwnPlaying(false))
    setOwnPlaying(next)
    return true
  }

  useVinylClock(playing && !media && value === undefined && !scratching && duration > 0, (seconds) => {
    const next = Math.min(duration, ownTime + seconds)
    seek(next, "playback", undefined)
    if (next >= duration) setPlaying(false, "playback", undefined)
  })

  const onSlider = (next: number, change: SliderValueChangeDetails) => {
    if (!seek(next, change.reason, change.event)) change.cancel()
  }

  const onPointerDown = (event: ReactPointerEvent<HTMLElement>) => {
    if (disabled || event.button !== 0 || duration <= 0) return
    const point = recordPointUnder(event)
    if (!point || point.distance > 1) return
    event.preventDefault()
    event.currentTarget.setPointerCapture(event.pointerId)
    const resume = playing
    if (resume) playMedia(media?.current, false, () => {})
    scratch.current = { pointer: event.pointerId, from: point.angle, time, resume }
    setScratching(true)
    slider.focus()
  }

  const onPointerMove = (event: ReactPointerEvent<HTMLElement>) => {
    const active = scratch.current
    if (active?.pointer !== event.pointerId) return
    const point = recordPointUnder(event)
    if (!point) return
    const delta = ((((point.angle - active.from + Math.PI) % fullTurn) + fullTurn) % fullTurn) - Math.PI
    active.from = point.angle
    active.time = Math.max(0, Math.min(duration, active.time + (delta / fullTurn) * secondsPerTurn))
    seek(active.time, "scratch", event.nativeEvent)
  }

  const endScratch = (event: ReactPointerEvent<HTMLElement>) => {
    const ended = scratch.current
    if (ended?.pointer !== event.pointerId) return
    scratch.current = null
    setScratching(false)
    if (ended.resume) playMedia(media?.current, true, () => setOwnPlaying(false))
  }

  const state = { disabled, playing, time, duration }

  return (
    <VinylScrubberRoot
      duration={duration}
      playing={playing}
      disabled={disabled}
      seek={(seconds, event) => seek(seconds, "imperative", event)}
      setPlaying={(next, event) => setPlaying(next, "imperative", event)}
      aria-label={label}
      className={cn(
        "flex w-full flex-col overflow-hidden rounded-surface border bg-card text-card-foreground shadow-surface",
        typeof className === "function" ? className(state) : className,
      )}
    >
      <div
        ref={deck}
        data-slot="vinyl-deck"
        data-playing={playing && !scratching ? "" : undefined}
        data-scratching={scratching ? "" : undefined}
        data-disabled={disabled ? "" : undefined}
      >
        <div
          ref={turntable}
          data-slot="vinyl-turntable"
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={endScratch}
          onPointerCancel={endScratch}
        >
          <Drawing title={title} subtitle={subtitle} />
        </div>
        <div data-slot="vinyl-panel">
          <div data-slot="vinyl-time">
            <output aria-hidden="true">{clock(time)}</output>
            <span aria-hidden="true">{`/ ${clock(duration)}`}</span>
          </div>
          <Slider
            controller={slider}
            value={time}
            onValueChange={onSlider}
            min={0}
            max={Math.max(duration, step)}
            step={step}
            largeStep={Math.max(step, Math.round(30 / step) * step)}
            disabled={disabled || duration <= 0}
            format={(seconds: number) => `${clock(seconds)} / ${clock(duration)}`}
          >
            <SliderControl data-peaks={peaks && peaks.length > 0 ? "" : undefined}>
              <Waveform peaks={peaks} />
              <SliderTrack>
                <SliderThumb aria-label={labels.position} className="touch-target" />
              </SliderTrack>
            </SliderControl>
          </Slider>
          <ControlTooltip label={labels.play}>
            <Toggle
              aria-label={labels.play}
              pressed={playing}
              disabled={disabled || duration <= 0}
              onPressedChange={(next, change) => {
                if (!setPlaying(next, change.reason, change.event)) change.cancel()
              }}
            >
              <ToggleIcon>{playing ? <PauseIcon /> : <PlayIcon />}</ToggleIcon>
            </Toggle>
          </ControlTooltip>
        </div>
      </div>
    </VinylScrubberRoot>
  )
}

export { VinylScrubber, vinylScrubberLabels }
export type { VinylChangeDetails, VinylScrubberLabels, VinylScrubberProps, VinylScrubberState }

import { definePrimitive } from "@ui-sdk/core"

import { settled, unavailable } from "@/lib/action-refusal"

/** Moves the playhead or starts and stops playback; returns `false` when the app cancelled it. */
type VinylSeek = (seconds: number, event: Event | undefined) => boolean
type VinylPlay = (playing: boolean, event: Event | undefined) => boolean

type VinylScrubberOptions = {
  duration?: number
  playing?: boolean
  disabled?: boolean
  seek?: VinylSeek
  setPlaying?: VinylPlay
}

const clockPattern = /^(?:(\d+):)?(\d{1,2}):(\d{2}(?:\.\d+)?)$/

/** Seconds from a number or a `"m:ss"` / `"h:mm:ss"` string. */
function secondsOf(time: unknown) {
  if (typeof time === "number") return Number.isFinite(time) ? time : undefined
  if (typeof time !== "string") return undefined
  const match = clockPattern.exec(time.trim())
  if (!match) return undefined
  return Number(match[1] ?? 0) * 3600 + Number(match[2]) * 60 + Number(match[3])
}

function ready(options: VinylScrubberOptions, action: string, event: Event | undefined, needsDuration = true) {
  if (options.disabled) return unavailable(action, "isn't available while the player is disabled", { event })
  const { duration, seek, setPlaying } = options
  if (!seek || !setPlaying) return unavailable(action, "isn't available: the player isn't ready", { event })
  if (needsDuration && (!duration || !Number.isFinite(duration))) {
    return unavailable(action, "isn't available until the media's duration is known", { event })
  }
  return { duration: duration ?? 0, seek, setPlaying }
}

/** A media timeline's agent surface: the record is UI SDK's slider in seconds, with playback beside it. */
const vinylScrubber = definePrimitive({
  name: "vinyl-scrubber",
  options: { duration: "value", playing: "value", disabled: "value", seek: "value", setPlaying: "value" },
  // Workaround: not `disabled`: the bridge would hide every action from a disabled part without saying why.
  state: (options: VinylScrubberOptions) => ({ inert: Boolean(options.disabled), playing: Boolean(options.playing) }),
  sync: (options) => ({ inert: Boolean(options.disabled), playing: Boolean(options.playing) }),
  api: (context) => ({
    /** Moves the playhead to a time: seconds, or `"m:ss"`, from 0 to the duration. */
    seek(time: number | string, event?: Event) {
      const player = ready(context.options(), "seek", event)
      if (player === false) return false
      const seconds = secondsOf(time)
      if (seconds === undefined || seconds < 0 || seconds > player.duration) {
        return unavailable(
          "seek",
          `takes 0 to ${String(Math.floor(player.duration))} seconds or "m:ss", not ${JSON.stringify(time)}`,
          { event },
        )
      }
      return settled(player.seek(seconds, event), "seek", { event })
    },
    /** Starts playback; `true` when it already plays. */
    play(event?: Event) {
      const player = ready(context.options(), "play", event)
      if (player === false) return false
      if (context.options().playing) return true
      return settled(player.setPlaying(true, event), "play", { event })
    },
    /** Pauses playback; `true` when it is already paused. */
    pause(event?: Event) {
      const player = ready(context.options(), "pause", event, false)
      if (player === false) return false
      if (!context.options().playing) return true
      return settled(player.setPlaying(false, event), "pause", { event })
    },
  }),
  slots: (slot) => ({
    root: slot({
      role: "group",
      attrs: (state) => ({
        "data-disabled": state.inert ? "" : undefined,
        "data-playing": state.playing ? "" : undefined,
      }),
    }),
  }),
  agent: { actions: ["seek", "play", "pause"] },
})

export { secondsOf, vinylScrubber }
export type { VinylPlay, VinylScrubberOptions, VinylSeek }

type Vector = { x: number; y: number; z: number }

/** One turn of a record at 33⅓ rpm, in seconds. */
const secondsPerTurn = 1.8

const cameraFovDegrees = 26
const cameraDistance = 112
const cameraElevationDegrees = 26
const cameraTarget: Vector = { x: 0, y: 16, z: 0 }
const cameraLift = 14

const deckTop = 11.65
const recordRadius = 15
const labelRadius = 5
const recordCenter: Vector = { x: -5.5, y: deckTop + 1.4, z: 2 }
const recordTop = recordCenter.y + 0.09

const armOuterGrooveRadians = -0.324
const armSweepRadians = 0.5

const add = (a: Vector, b: Vector, scale = 1): Vector => ({
  x: a.x + b.x * scale,
  y: a.y + b.y * scale,
  z: a.z + b.z * scale,
})
const dot = (a: Vector, b: Vector) => a.x * b.x + a.y * b.y + a.z * b.z
const cross = (a: Vector, b: Vector): Vector => ({
  x: a.y * b.z - a.z * b.y,
  y: a.z * b.x - a.x * b.z,
  z: a.x * b.y - a.y * b.x,
})
const unit = (a: Vector): Vector => {
  const length = Math.hypot(a.x, a.y, a.z) || 1
  return { x: a.x / length, y: a.y / length, z: a.z / length }
}

const elevation = (cameraElevationDegrees * Math.PI) / 180
const cameraPosition: Vector = {
  x: 0,
  y: cameraLift + Math.sin(elevation) * cameraDistance,
  z: Math.cos(elevation) * cameraDistance,
}
const forward = unit(add(cameraTarget, cameraPosition, -1))
const right = unit(cross(forward, { x: 0, y: 1, z: 0 }))
const up = cross(right, forward)
const halfHeight = Math.tan((cameraFovDegrees * Math.PI) / 360)

/** Where a point of the scene lands on a stage of this width-to-height ratio: 0 to 1 from the left and the top. */
function projectToStage(point: Vector, aspect: number) {
  const offset = add(point, cameraPosition, -1)
  const depth = dot(offset, forward)
  return {
    x: (dot(offset, right) / (depth * halfHeight * aspect) + 1) / 2,
    y: (1 - dot(offset, up) / (depth * halfHeight)) / 2,
  }
}

/**
 * The point of the record's face under a point of the stage (0 to 1 from the left and the top): its angle around the
 * spindle in radians, growing clockwise as seen from above, and its distance from the spindle relative to the
 * record's radius (over 1 off the record). `null` when the point looks above the horizon.
 */
function recordPointAt(stageX: number, stageY: number, aspect: number) {
  const across = (stageX * 2 - 1) * halfHeight * aspect
  const along = (1 - stageY * 2) * halfHeight
  const ray = add(add(forward, right, across), up, along)
  if (ray.y >= 0) return null
  const hit = add(cameraPosition, ray, (recordTop - cameraPosition.y) / ray.y)
  const dx = hit.x - recordCenter.x
  const dz = hit.z - recordCenter.z
  return { angle: Math.atan2(dz, dx), distance: Math.hypot(dx, dz) / recordRadius }
}

/** A point on the record's face at an angle (clockwise from above) and a distance relative to its radius. */
function pointOnRecord(angle: number, distance: number): Vector {
  return {
    x: recordCenter.x + Math.cos(angle) * distance * recordRadius,
    y: recordTop,
    z: recordCenter.z + Math.sin(angle) * distance * recordRadius,
  }
}

/** The record's turn at a time, in radians clockwise. */
const recordTurn = (seconds: number) => ((seconds / secondsPerTurn) % 1) * Math.PI * 2

/** The tonearm's swing over the record: the outer groove at progress 0, the inner one at 1. */
const armAngle = (progress: number) => armOuterGrooveRadians - Math.max(0, Math.min(1, progress)) * armSweepRadians

export {
  armAngle,
  cameraFovDegrees,
  cameraPosition,
  cameraTarget,
  deckTop,
  labelRadius,
  pointOnRecord,
  projectToStage,
  recordCenter,
  recordPointAt,
  recordRadius,
  recordTurn,
  secondsPerTurn,
}
export type { Vector }

import { useSyncExternalStore, type RefObject } from "react"

/** What the scrubber reads from a media element: its time and duration in seconds, and whether it plays. */
type MediaReading = { time: number; duration: number; playing: boolean }

const mediaEvents = ["timeupdate", "durationchange", "loadedmetadata", "play", "pause", "ended", "seeked", "emptied"]
const noMedia = "0|0|0"

function readingOf(snapshot: string): MediaReading {
  const [time = "0", duration = "0", playing = "0"] = snapshot.split("|")
  return { time: Number(time), duration: Number(duration) || 0, playing: playing === "1" }
}

type MediaRef = RefObject<HTMLMediaElement | null>

const subscribers = new WeakMap<MediaRef, (notify: () => void) => () => void>()

function subscriberFor(media: MediaRef) {
  const known = subscribers.get(media)
  if (known) return known
  const subscribe = (notify: () => void) => {
    const element = media.current
    if (!element) return () => {}
    for (const name of mediaEvents) element.addEventListener(name, notify)
    return () => {
      for (const name of mediaEvents) element.removeEventListener(name, notify)
    }
  }
  subscribers.set(media, subscribe)
  return subscribe
}

const subscribeToNothing = () => () => {}

function snapshotOf(media: MediaRef | undefined) {
  const element = media?.current
  if (!element) return noMedia
  const duration = Number.isFinite(element.duration) ? element.duration : 0
  return `${String(element.currentTime)}|${String(duration)}|${element.paused || element.ended ? "0" : "1"}`
}

/** Follows an `HTMLMediaElement`'s time, duration and playback through its events; nothing when there is none. */
function useVinylMedia(media: MediaRef | undefined): MediaReading | undefined {
  const snapshot = useSyncExternalStore(
    media ? subscriberFor(media) : subscribeToNothing,
    () => snapshotOf(media),
    () => noMedia,
  )
  return media ? readingOf(snapshot) : undefined
}

export { useVinylMedia }
export type { MediaReading }

import { CanvasTexture, RepeatWrapping, SRGBColorSpace, type Texture } from "three"

type Surface = HTMLCanvasElement | OffscreenCanvas
type Context2D = CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D

function surface(size: number): Surface {
  if (typeof OffscreenCanvas === "function") return new OffscreenCanvas(size, size)
  const canvas = document.createElement("canvas")
  canvas.width = size
  canvas.height = size
  return canvas
}

function context2d(canvas: Surface): Context2D | null {
  return typeof OffscreenCanvas === "function" && canvas instanceof OffscreenCanvas
    ? canvas.getContext("2d")
    : canvas.getContext("2d")
}

const isBitmap = (image: unknown): image is ImageBitmap =>
  typeof ImageBitmap === "function" && image instanceof ImageBitmap

function seededRandom(seed: number) {
  let state = seed
  return () => {
    state = (state + 0x6d2b79f5) | 0
    let mixed = Math.imul(state ^ (state >>> 15), 1 | state)
    mixed = (mixed + Math.imul(mixed ^ (mixed >>> 7), 61 | mixed)) ^ mixed
    return ((mixed ^ (mixed >>> 14)) >>> 0) / 4294967296
  }
}

function canvasTexture(size: number, draw: (context: Context2D, size: number) => void, color: boolean) {
  const canvas = surface(size)
  const context = context2d(canvas)
  if (context) draw(context, size)
  const texture = new CanvasTexture(canvas)
  if (color) texture.colorSpace = SRGBColorSpace
  texture.anisotropy = 8
  return texture
}

function repeating(texture: Texture, times: number) {
  texture.wrapS = RepeatWrapping
  texture.wrapT = RepeatWrapping
  texture.repeat.set(times, times)
  return texture
}

function noise(context: Context2D, size: number, base: number, spread: number, grain: boolean, seed: number) {
  const random = seededRandom(seed)
  const image = context.createImageData(size, size)
  for (let index = 0; index < size * size; index++) {
    const value = base + (random() - 0.5) * spread
    image.data[index * 4] = value
    image.data[index * 4 + 1] = value
    image.data[index * 4 + 2] = value
    image.data[index * 4 + 3] = 255
  }
  context.putImageData(image, 0, 0)
  if (!grain) return
  context.globalAlpha = 0.18
  for (let index = 0; index < size * 3; index++) {
    context.fillStyle = random() > 0.5 ? "#fff" : "#000"
    context.beginPath()
    context.arc(random() * size, random() * size, 0.6 + random() * 2.2, 0, Math.PI * 2)
    context.fill()
  }
  context.globalAlpha = 1
}

function grilleHoles(context: Context2D, size: number) {
  context.fillStyle = "#fff"
  context.fillRect(0, 0, size, size)
  context.fillStyle = "#000"
  for (let y = 4; y < size; y += 8) {
    for (let x = (y / 8) % 2 ? 8 : 4; x < size; x += 8) {
      context.beginPath()
      context.arc(x, y, 2.3, 0, Math.PI * 2)
      context.fill()
    }
  }
}

const runOutGrooves = [0.62, 0.78, 0.92]

function grooves(context: Context2D, size: number) {
  const random = seededRandom(33)
  const center = size / 2
  context.fillStyle = "#808080"
  context.fillRect(0, 0, size, size)
  for (let radius = center * 0.4; radius < center * 0.985; radius += 1.6) {
    const gap = runOutGrooves.some((groove) => Math.abs(radius / center - groove) < 0.006)
    context.strokeStyle = gap ? "#9a9a9a" : random() > 0.5 ? "#6c6c6c" : "#767676"
    context.lineWidth = gap ? 1.6 : 0.8
    context.beginPath()
    context.arc(center, center, radius, 0, Math.PI * 2)
    context.stroke()
  }
}

function tangents(context: Context2D, size: number) {
  const image = context.createImageData(size, size)
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const dx = x - size / 2 + 0.5
      const dy = size / 2 - y - 0.5
      const length = Math.hypot(dx, dy) || 1
      const index = (y * size + x) * 4
      image.data[index] = ((-dy / length) * 0.5 + 0.5) * 255
      image.data[index + 1] = ((dx / length) * 0.5 + 0.5) * 255
      image.data[index + 2] = 255
      image.data[index + 3] = 255
    }
  }
  context.putImageData(image, 0, 0)
}

export { canvasTexture, grilleHoles, grooves, isBitmap, noise, repeating, tangents }
